-- Locations from ZIP codes, installer document uploads, and file storage for documents, drawings,
-- job photos and profile photos. Runs after 20261020000000_job_routing.sql.
-- The ZIP data itself loads in 20261021000100_zip_centroids_data.sql (generated by scripts/zip-centroids.mjs).

-- ---------- ZIP code centres ----------
-- One point per ZIP code (Census ZCTA internal point). Routing only needs the ZIP's centre until the
-- site address is known. Public Census data, so anyone may read it.
create table dir_zip_centroids (
  zip char(5) primary key,
  lat double precision not null,
  lng double precision not null
);
alter table dir_zip_centroids enable row level security;
create policy public_read on dir_zip_centroids for select using (true);
create policy admin_all on dir_zip_centroids for all using (dir_is_admin()) with check (dir_is_admin());
grant select on dir_zip_centroids to anon, authenticated;

-- Fills a job's location from its ZIP: on insert when no location is given, on update only when the
-- ZIP changes and the same update doesn't set a location. An unknown ZIP leaves the location empty,
-- so routing flags the job ('Job location missing') instead of using an old point.
-- Named so it fires before the other before-triggers (they run in name order).
create function dir_jobs_location() returns trigger
language plpgsql as $$
begin
  if tg_op = 'INSERT' then
    if new.lat is null then
      select z.lat, z.lng into new.lat, new.lng from dir_zip_centroids z where z.zip = new.zip;
    end if;
  elsif new.zip is distinct from old.zip and (new.lat, new.lng) is not distinct from (old.lat, old.lng) then
    new.lat := null; new.lng := null;
    select z.lat, z.lng into new.lat, new.lng from dir_zip_centroids z where z.zip = new.zip;
  end if;
  return new;
end $$;

create trigger dir_jobs_a_location before insert or update on dir_jobs
for each row execute function dir_jobs_location();

-- Same for an installer's base: their ZIP sets the point their service radius is measured from.
create function dir_installers_location() returns trigger
language plpgsql as $$
begin
  if tg_op = 'INSERT' then
    if new.lat is null then
      select z.lat, z.lng into new.lat, new.lng from dir_zip_centroids z where z.zip = new.base_zip;
    end if;
  elsif new.base_zip is distinct from old.base_zip and (new.lat, new.lng) is not distinct from (old.lat, old.lng) then
    new.lat := null; new.lng := null;
    select z.lat, z.lng into new.lat, new.lng from dir_zip_centroids z where z.zip = new.base_zip;
  end if;
  return new;
end $$;

create trigger dir_installers_a_location before insert or update on dir_installers
for each row execute function dir_installers_location();

-- ---------- installer document uploads ----------
-- Installers upload insurance certificates and registrations (e.g. a renewal) in the portal.
-- Next Partitions reviews each one and updates dir_installer_checks; the upload itself changes nothing.
-- path is the file's name in the dir-documents bucket and starts with the installer's id folder.
create table dir_document_uploads (
  id uuid primary key default gen_random_uuid(),
  installer_id uuid not null references dir_installers (id) on delete cascade,
  check_type dir_check_type not null,
  path text not null,
  uploaded_at timestamptz not null default now(),
  reviewed_at timestamptz,
  review_note text
);
create index on dir_document_uploads (installer_id);
create index on dir_document_uploads (uploaded_at) where reviewed_at is null;

alter table dir_document_uploads enable row level security;
create policy admin_all on dir_document_uploads for all using (dir_is_admin()) with check (dir_is_admin());
create policy own_uploads_read on dir_document_uploads for select using (installer_id = dir_my_installer_id());
-- Insert only: installers can't edit or delete an upload once it's sent.
create policy own_uploads_add on dir_document_uploads for insert with check (
  installer_id = dir_my_installer_id() and reviewed_at is null and review_note is null
  and split_part(path, '/', 1) = installer_id::text
);

-- Installers can't backdate an upload. Every upload is queued for the job coordinator to review.
create function dir_document_uploads_stamp() returns trigger
language plpgsql as $$
begin
  if dir_called_by_app_user() and not dir_is_admin() then
    new.uploaded_at := now();
  end if;
  return new;
end $$;

create trigger dir_document_uploads_stamp before insert on dir_document_uploads
for each row execute function dir_document_uploads_stamp();

create function dir_document_uploads_outbox() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform dir_enqueue('document_uploaded', null, new.installer_id,
    jsonb_build_object('upload_id', new.id, 'check_type', new.check_type, 'path', new.path));
  return null;
end $$;

create trigger dir_document_uploads_outbox after insert on dir_document_uploads
for each row execute function dir_document_uploads_outbox();

-- ---------- file storage ----------
-- Four buckets. Each file's first folder says who may reach it:
--   dir-documents/<installer_id>/<file>     private: insurance, registrations (installer and admins)
--   dir-drawings/<job_id>/<file>            private: shop drawings (admins upload; invited installers read)
--   dir-job-photos/<job_id>/<file>          private: install photos (chosen installer, after release)
--   dir-profile-photos/<installer_id>/<file> public: profile and job-gallery photos
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('dir-documents', 'dir-documents', false, 10485760, array['application/pdf', 'image/jpeg', 'image/png']),
  ('dir-drawings', 'dir-drawings', false, 26214400, array['application/pdf', 'image/jpeg', 'image/png']),
  ('dir-job-photos', 'dir-job-photos', false, 10485760, array['image/jpeg', 'image/png', 'image/webp', 'image/heic']),
  ('dir-profile-photos', 'dir-profile-photos', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

-- A folder name as a uuid, or null when it isn't one (so a stray path can't raise an error).
create function dir_uuid_or_null(t text) returns uuid
language sql immutable as $$
  select case when t ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then t::uuid end;
$$;

-- The first folder of an object's name, as a uuid.
create function dir_object_owner_id(name text) returns uuid
language sql immutable as $$
  select dir_uuid_or_null((storage.foldername(name))[1]);
$$;

-- Admins: everything in the directory's buckets (and nothing else in the site's storage).
create policy dir_admin_all on storage.objects for all
  using (bucket_id in ('dir-documents', 'dir-drawings', 'dir-job-photos', 'dir-profile-photos') and dir_is_admin())
  with check (bucket_id in ('dir-documents', 'dir-drawings', 'dir-job-photos', 'dir-profile-photos') and dir_is_admin());

-- Documents: an installer adds and reads files in their own folder only.
create policy dir_documents_own_read on storage.objects for select
  using (bucket_id = 'dir-documents' and dir_object_owner_id(name) = dir_my_installer_id());
create policy dir_documents_own_add on storage.objects for insert
  with check (bucket_id = 'dir-documents' and dir_object_owner_id(name) = dir_my_installer_id());

-- Drawings: installers invited to price the job can read them. Only admins upload.
create policy dir_drawings_invited_read on storage.objects for select
  using (bucket_id = 'dir-drawings' and dir_can_see_job(dir_object_owner_id(name)));

-- Job photos: only the chosen installer, only once the job is released to them.
create policy dir_job_photos_read on storage.objects for select
  using (bucket_id = 'dir-job-photos' and dir_job_released_to(dir_object_owner_id(name), dir_my_installer_id()));
create policy dir_job_photos_add on storage.objects for insert
  with check (bucket_id = 'dir-job-photos' and dir_job_released_to(dir_object_owner_id(name), dir_my_installer_id()));

-- Profile photos: public to read; installers manage their own folder.
create policy dir_profile_photos_read on storage.objects for select using (bucket_id = 'dir-profile-photos');
create policy dir_profile_photos_add on storage.objects for insert
  with check (bucket_id = 'dir-profile-photos' and dir_object_owner_id(name) = dir_my_installer_id());
create policy dir_profile_photos_edit on storage.objects for update
  using (bucket_id = 'dir-profile-photos' and dir_object_owner_id(name) = dir_my_installer_id())
  with check (bucket_id = 'dir-profile-photos' and dir_object_owner_id(name) = dir_my_installer_id());
create policy dir_profile_photos_remove on storage.objects for delete
  using (bucket_id = 'dir-profile-photos' and dir_object_owner_id(name) = dir_my_installer_id());
